//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `failed_attempts` failed calls.
    pub(crate) fn delay_for_retry(&self, failed_attempts: u32) -> u64 {
        let exponent = failed_attempts.saturating_sub(1);
        let multiplier = 1u64.checked_shl(exponent).unwrap_or(u64::MAX);
        self.base_delay_ms
            .checked_mul(multiplier)
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delays_grow_and_saturate() {
        let config = RetryConfig { max_attempts: 5, base_delay_ms: 10, max_delay_ms: 25 };
        assert_eq!(config.delay_for_retry(1), 10);
        assert_eq!(config.delay_for_retry(2), 20);
        assert_eq!(config.delay_for_retry(3), 25);
        assert_eq!(config.delay_for_retry(4), 25);
    }

    #[test]
    fn huge_exponents_do_not_overflow() {
        let config = RetryConfig { max_attempts: u32::MAX, base_delay_ms: u64::MAX, max_delay_ms: 99 };
        assert_eq!(config.delay_for_retry(u32::MAX), 99);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    if config.max_attempts == 0 {
        return Err(RetryError::Permanent("max_attempts must be at least 1".into()));
    }

    let mut failed_attempts = 0;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && failed_attempts + 1 < config.max_attempts => {
                failed_attempts += 1;
                sleeper.sleep_ms(config.delay_for_retry(failed_attempts));
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig { max_attempts, base_delay_ms: 10, max_delay_ms: 25 }
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 3 { Err(RetryError::Transient("temporary".into())) } else { Ok(()) }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_are_returned_without_retry() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let error = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });
        assert_eq!(error, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_first_call() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(2), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });
        assert!(matches!(result, Err(RetryError::Transient(_))));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![10]);
    }
}
